-- Read-only, explicitly whitelisted input for revenue research. No credentials or media.
-- Required psql argument: --set=snapshot_reference=ISO_TIMESTAMP_OF_SOURCE_DUMP
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout = '90s';
SELECT jsonb_build_object(
 'snapshot_reference', :'snapshot_reference',
 'extracted_at', now(),
 'services', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, placement_id, machine_number, kind, service_date, occurred_at, technician_id, game_counter, prize_counter, test_games, new_games, new_prizes, price_per_game_snapshot, revenue, toy_cost, cashless_amount, cash_amount, is_financial_anomaly, notes, created_by, created_at, updated_at, counter_divisor_applied, revenue_to_cost_ratio FROM services ORDER BY placement_id, occurred_at, id) t),
 'machines', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT machine_number, machine_type, model, price_per_game, status, min_service_days, max_service_days, created_at, updated_at, counter_divisor, default_toy_set_id, target_payout_percent FROM machines ORDER BY machine_number) t),
 'placements', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, machine_number, location_id, started_at, ended_at, initial_game_counter, initial_prize_counter, installed_by, closed_by, close_reason, address FROM machine_placements ORDER BY id) t),
 'locations', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, parent_id, name, address, timezone, status, min_service_days, max_service_days, closed_at FROM locations ORDER BY id) t),
 'staff', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, full_name, role, is_active, is_field_technician FROM staff ORDER BY id) t),
 'toy_distributions', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT service_id, toy_id, quantity, unit_cost_snapshot FROM toy_distributions ORDER BY service_id, toy_id) t),
 'toys', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, name, unit_cost, is_active FROM toys ORDER BY id) t),
 'initial_toys', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT placement_id, toy_id, quantity, unit_cost_snapshot FROM placement_initial_toys ORDER BY placement_id, toy_id) t),
 'claw_settings', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, machine_number, effective_at, strong, medium, weak, prize_set, source, service_id, task_id, entered_by, note FROM claw_settings ORDER BY machine_number, effective_at, id) t),
 'machine_types', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT name, is_active, has_claw_settings, target_payout_percent FROM machine_types) t),
 'tasks', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, machine_number, location_id, assigned_to, title, details, status, due_date, created_at, closed_at, closed_by, close_note, claw_plan FROM technician_tasks WHERE created_at >= '2026-08-01' OR closed_at >= '2026-08-01' OR status::text <> 'CLOSED' ORDER BY id) t),
 'cashless_daily', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT matched_machine_number AS machine_number, matched_placement_id AS placement_id, terminal_id, (occurred_at AT TIME ZONE 'Europe/Moscow')::date AS day, match_status, unmatched_reason, count(*) AS transactions, sum(amount) AS amount, max(imported_at) AS last_imported_at, count(*) FILTER (WHERE imported_at > occurred_at + interval '7 days') AS late_imported_count FROM cashless_transactions WHERE occurred_at >= '2026-08-01T00:00:00+03' GROUP BY 1,2,3,4,5,6 ORDER BY 1,4) t),
 'terminal_bindings', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, terminal_id, machine_number, location_id, started_at, ended_at FROM terminal_bindings ORDER BY id) t),
 'machine_routes', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT machine_number, route_id FROM machine_routes) t),
 'routes', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, name, min_service_days, max_service_days FROM routes) t),
 'machine_technicians', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT machine_number, staff_id FROM machine_technicians) t),
 'counter_checks', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT service_id, entered_games, entered_prizes, status, detected_games, detected_prizes, created_at, checked_at, resolved_at FROM counter_photo_checks) t),
 'service_reviews', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT technician_id, machine_number, occurred_at, error_code, status, service_id, resolved_at, admin_comment, created_at FROM service_reviews WHERE occurred_at >= '2026-09-01' ORDER BY occurred_at) t),
 'draft_issues', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT technician_id, machine_number, occurred_at, error_code, error_message, reported_at FROM technician_draft_issues WHERE occurred_at >= '2026-09-01') t),
 'audit_changes', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, actor_id, occurred_at, entity, entity_id, action,
  jsonb_strip_nulls(jsonb_build_object('machine_number',old_data->'machine_number','service_id',old_data->'service_id','game_counter',old_data->'game_counter','prize_counter',old_data->'prize_counter','counter_divisor',old_data->'counter_divisor','counter_divisor_applied',old_data->'counter_divisor_applied','price_per_game',old_data->'price_per_game','price_per_game_snapshot',old_data->'price_per_game_snapshot','revenue',old_data->'revenue','new_games',old_data->'new_games','initial_game_counter',old_data->'initial_game_counter','initial_prize_counter',old_data->'initial_prize_counter','started_at',old_data->'started_at','ended_at',old_data->'ended_at','status',old_data->'status')) AS old_values,
  jsonb_strip_nulls(jsonb_build_object('machine_number',new_data->'machine_number','service_id',new_data->'service_id','game_counter',new_data->'game_counter','prize_counter',new_data->'prize_counter','counter_divisor',new_data->'counter_divisor','counter_divisor_applied',new_data->'counter_divisor_applied','price_per_game',new_data->'price_per_game','price_per_game_snapshot',new_data->'price_per_game_snapshot','revenue',new_data->'revenue','new_games',new_data->'new_games','initial_game_counter',new_data->'initial_game_counter','initial_prize_counter',new_data->'initial_prize_counter','started_at',new_data->'started_at','ended_at',new_data->'ended_at','status',new_data->'status')) AS new_values
  FROM audit_log WHERE occurred_at >= '2026-08-01' AND entity IN ('services','service','machines','machine','machine_placements','placement','terminal_bindings','terminal_binding') ORDER BY id) t),
 'parser_runs', (SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]') FROM (SELECT id, started_at, finished_at, window_from, pages_fetched, rows_received, rows_inserted, rows_duplicate, rows_matched, status FROM parser_runs WHERE started_at >= '2026-09-01' ORDER BY id) t)
);
COMMIT;
